sql.where:
b.is_active = true
AND b.status = #{status}
AND b.category_id = #{categoryId}

    AND EXISTS (SELECT 1 FROM block_tag bt WHERE bt.block_id = b.id AND bt.tag_id IN
    #{tagId})

AND b.title ILIKE '%' || #{keyword} || '%'

mapper.select:



    ORDER BY b.play_count DESC, b.created_at DESC, b.id DESC
    ORDER BY b.created_at DESC, b.id DESC

LIMIT #{limit} OFFSET #{offset}
